function validProfilePhoto(src){return /^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(String(src||''))}
function userAvatar(user,cls='user-avatar'){const name=String(user?.displayName||user?.username||'?'),photo=user?.photo;return validProfilePhoto(photo)?`<span class="${cls}"><img src="${photo}" alt="${esc(name)}"></span>`:`<span class="${cls}">${esc(name.slice(0,2).toUpperCase())}</span>`}
function allowedPage(k){if(k==='tdmphotos'||k==='users'||k==='settings')return state.me?.role==='owner';if(k==='presencetrends'||k==='availability')return false;return Boolean(state.me)&&(k==='notifications'||state.me.role==='owner'||(state.me.pages||[]).includes(k));}
function allowedAction(k){return state.me?.role==='owner'||(state.me?.actions||[]).includes(k)}
