function preset(v){if(!v)return;const today=new Date(),day=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');let from='',to='';if(v==='latest'){from=to=rows.map(r=>r._date).sort().at(-1)||''}else if(v!=='all'){to=day(today);if(v==='today')from=to;else if(v==='month')from=to.slice(0,7)+'01';else{today.setDate(today.getDate()-Number(v)+1);from=day(today)}}state.filters={...state.filters,from,to};rememberFilters();state.page=0;render()}
function endSession(message=''){sessionEpoch++;alertKeys=[];unreadKeys=[];lastSoundKeys=new Set();
 api.setToken('');data=null;rows=[];state.me=null;state.users=[];state.selectedStore=null;state.filters={};state.filtersByTab={dashboard:{}};state.photoClientCode='';state.tab='dashboard';state.appSettings=null;state.busy=false;
 if(map){map.stop();map.remove();map=null;}document.querySelectorAll('dialog[open]').forEach(d=>d.close());loginScreen(message);
}
async function refresh(initial=false,preparedBundle=null){
 if(state.busy)return;const epoch=sessionEpoch;state.busy=true;if($('#refresh'))$('#refresh').disabled=true;
 try{
  const bundle=preparedBundle||await api.call('bootstrap',{format:'columns'});if(epoch!==sessionEpoch)return;
  state.me=bundle.user;const next=prepareBundle(bundle,data);state.appSettings=bundle.settings||{};state.users=bundle.users||[];next.appSettings=state.appSettings;
  if(state.appSettings.analysis)state.settings={...state.settings,...state.appSettings.analysis};
  state.settings.tabs=state.appSettings.tabs||state.settings.tabs||{};state.theme=state.appSettings.theme||state.theme;
  data=next;rows=normalize(data.sheets.All.rows).map(r=>{const RTM=coreRtmName(r.RTM);return RTM?{...r,RTM}:null}).filter(Boolean);
  if(!state.columns)state.columns=['Date','Rep','RTM','Client','Client Code','Governorate','Area Name','Outlet Type','Availability','Duration (min)','Gorilla Share of Shelf'];
  const known=read('gorilla-known-columns',[]);if(known.length)state.columns.push(...data.sheets.All.columns.filter(c=>!known.includes(c)));
  localStorage.setItem('gorilla-known-columns',JSON.stringify(data.sheets.All.columns));
  state.columns=[...new Set(state.columns)].filter(c=>data.sheets.All.columns.includes(c));if(!state.columns.length)state.columns=data.sheets.All.columns.slice(0,10);
  updateAlerts();state.busy=false;render();
  if(initial)void checkFreshness(false);
  return true;
 }catch(e){state.busy=false;if(e.code==='UNAUTHORIZED')return endSession(T('Your session ended. Please sign in again.','انتهت الجلسة. سجّل الدخول مرة أخرى.'));if(data){render();toast(T('Refresh failed. Previous data retained: ','فشل التحديث. البيانات السابقة محفوظة: ')+e.message)}else loginScreen(e.message)}
}
async function checkFreshness(manual=false,scan=false){
 if(checking||state.busy||!state.me)return;checking=true;const epoch=sessionEpoch;
 if(manual)toast(T('Checking Drive for new files…','جاري فحص الملفات الجديدة على Drive…'));
 if($('#refresh'))$('#refresh').disabled=true;
 try{const result=await api.call(manual||scan?'sync':'status');if(epoch!==sessionEpoch)return;
  if(manual||result.sync?.revision!==data?.sync?.revision){if(!await refresh(false))return;}
  if(result.sync?.errors?.length)toast(result.sync.errors.join(' · '));
  else if(manual)toast(result.busy?T('File processing is already running. New data will appear automatically.','معالجة الملفات شغالة بالفعل. البيانات الجديدة هتظهر تلقائيًا.'):T('Latest available data loaded','تم تحميل أحدث بيانات متاحة'));
 }catch(e){if(e.code==='UNAUTHORIZED')endSession(T('Please sign in again','سجّل الدخول مرة أخرى'));else if(manual)toast(e.message);}
 finally{checking=false;if($('#refresh'))$('#refresh').disabled=false;}
}
function updateAlerts(){
 const baselineKey='gorilla-alert-baseline:'+state.me.username,previous=read(baselineKey,null),routeRows=data?.sheets?.RoutePlan?.rows||[],routeFile=routeRows[0]?._sourceFile||'',routeRevision=routeFile+'|'+(routeRows[0]?._sourceModified||routeRows[0]?._sourceDate||''),round=state.appSettings?.roundControl?.current||{},newCount=newStoreRows().filter(r=>r['Is Current Round']==='Yes'&&r.Source==='New TDM').length,current={revision:data.sync?.revision||'',routeFile:routeFile,routeRevision:routeRevision,round:String(round.name||'')+'|'+String(round.start||''),newCount:newCount,errors:(data.sync?.errors||[]).join(' | ')};
 let added=false;
 if(previous){
  if(current.revision&&current.revision!==previous.revision)added=addImportantNotification('data',T('Source data updated','تم تحديث بيانات المصدر'),T('Latest synchronized data is ready.','أحدث البيانات المتزامنة جاهزة.'),'data|'+current.revision)||added;
  if(current.routeFile&&current.routeRevision!==previous.routeRevision)added=addImportantNotification('route',T('Route Plan updated','تم تحديث Route Plan'),current.routeFile,'route|'+current.routeRevision)||added;
  if(current.round&&current.round!==previous.round)added=addImportantNotification('round',T('Round started / changed','تم بدء أو تغيير الراوند'),round.name||'', 'round|'+current.round)||added;
  if(Number(current.newCount)>Number(previous.newCount||0)){const delta=Number(current.newCount)-Number(previous.newCount||0);added=addImportantNotification('newstores',T('New Stores received','تم استلام محلات جديدة'),`${fmt(delta)} ${T('new store(s) added to the current round','محل جديد تمت إضافته للراوند الحالي')}`,'newstores|'+current.round+'|'+current.newCount)||added;}
  if(current.errors&&current.errors!==previous.errors)added=addImportantNotification('source-error',T('Important source problem','مشكلة مهمة في المصدر'),current.errors,'error|'+current.errors)||added;
 }
 localStorage.setItem(baselineKey,JSON.stringify(current));
 const entries=notificationEntries();unreadKeys=entries.filter(e=>!e.read).map(e=>e.key);
 const freshKeys=unreadKeys.filter(k=>!lastSoundKeys.has(k));
 if(added&&freshKeys.length){playAlert();toast(T('Important update received','تم استلام تحديث مهم'));void notifyDevice();}
 lastSoundKeys=new Set(unreadKeys);
}
