const NOTIFICATION_TTL=72*60*60*1000;
function notificationStorageKey(){return 'gorilla-notification-log:'+state.me.username}
function notificationEntries(){const now=Date.now(),key=notificationStorageKey(),entries=read(key,[]).filter(e=>e&&e.ts&&now-Number(e.ts)<=NOTIFICATION_TTL).sort((a,b)=>b.ts-a.ts);localStorage.setItem(key,JSON.stringify(entries));return entries}
function addImportantNotification(kind,title,detail,key){const entries=notificationEntries();if(entries.some(e=>e.key===key))return false;entries.unshift({key,kind,title,detail,ts:Date.now(),read:false});localStorage.setItem(notificationStorageKey(),JSON.stringify(entries));return true}
