async function exportData(format,scope){
  const selection=exportSelection(scope);
  const action=format==='pdf'?'print':'export';if(!allowedAction(action))return toast(T('This action is not permitted','غير مسموح بهذا الإجراء'));
  try{await api.call('authorize',{permission:action})}catch(e){return toast(e.message)}
 const {records,columns,name}=selection;
 if(!columns.length||!records.length){toast(T('No matching records to export','لا توجد سجلات مطابقة للتصدير'));return}
 if(format==='pdf'){
  $('#print-report')?.remove();const report=document.createElement('section');report.id='print-report';
  const content=columns.length<=16?simpleTable(records,columns):records.map(r=>`<section class="record-print"><h2>${esc(r.Client||r['Client Code']||'')} · ${esc(r.Date||'')}</h2><dl>${columns.map(c=>`<div><dt>${esc(fieldLabel(c))}</dt><dd>${cellHTML(r,c,false)}</dd></div>`).join('')}</dl></section>`).join('');
  report.innerHTML=`<h1>GORILLA · ${T('Field report','تقرير الميدان')}</h1><p>${esc(name)} · ${esc(data.source)} · ${esc(formatTimestamp(data.refreshed))}</p><p>${T('Filters','الفلاتر')}: ${esc(Object.entries(state.filters).filter(x=>x[1]).map(([k,v])=>fieldLabel(k)+': '+(k===STATUS_FIELD?statusText(v,state.lang):v)).join(' · ')||T('All data','كل البيانات'))}</p><p>${fmt(records.length)} ${T('visits · every matching row included','زيارة · يشمل كل الصفوف المطابقة')}</p>${content}`;
  document.body.append(report);document.body.classList.add('printing-report');window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-report');report.remove()},{once:true});toast(T('Choose Save as PDF','اختر حفظ كـ PDF'));window.print();return;
 }
 try{
     const bytes=format==='xlsx'?xlsxBytes(records,columns,state.lang):csvBytes(records,columns,state.lang);
   const blob=new Blob([bytes],{type:format==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'text/csv;charset=utf-8'});
   const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${name}-${new Date().toISOString().slice(0,10)}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast(T('Export complete','اكتمل التصدير'));
 }catch(e){toast(T('Export failed: ','فشل التصدير: ')+e.message)}
}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_gorilla_visits',description:'Apply a global search to the same visit views shown in this local dashboard.',inputSchema:{type:'object',properties:{search:{type:'string'}},required:['search'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.search!=='string'||Object.keys(input).some(k=>k!=='search'))throw Error('Expected search text');if(!data)throw Error('Data is not loaded');apply('search',input.search);return {visits:scoped().length};}})).catch(()=>{});}catch{}}
function groupNotificationCards(root){
 if(!root||root.querySelector('.notification-group'))return;
 const groups=new Map();root.querySelectorAll('.notification-record').forEach(el=>{const title=el.querySelector('strong')?.textContent||T('Updates','تحديثات');if(!groups.has(title))groups.set(title,[]);groups.get(title).push(el)});
 for(const [title,records] of groups){const section=document.createElement('details');section.className='notification-group';section.dataset.category=title;const summary=document.createElement('summary');summary.textContent=title+' · '+fmt(records.length);section.append(summary);records[0].before(section);records.forEach(r=>section.append(r));}
 if(root.id==='notification-list'&&!$('#notification-category')){const label=document.createElement('label');label.textContent=T('Category ','التصنيف ');const select=document.createElement('select');select.id='notification-category';const all=document.createElement('option');all.value='';all.textContent=T('All categories','كل التصنيفات');select.append(all);for(const title of groups.keys()){const option=document.createElement('option');option.value=option.textContent=title;select.append(option);}label.append(select);root.before(label);}
}
document.addEventListener('change',e=>{if(!['notification-read-filter','notification-category'].includes(e.target.id))return;const mode=$('#notification-read-filter')?.value||'all',category=$('#notification-category')?.value||'';document.querySelectorAll('#notification-list .notification-group').forEach(group=>{const records=[...group.querySelectorAll('.notification-record')];for(const row of records)row.hidden=mode!=='all'&&row.dataset.read!==(mode==='read'?'true':'false');const visible=records.filter(r=>!r.hidden).length;group.hidden=!visible||Boolean(category&&group.dataset.category!==category);group.querySelector('summary').textContent=group.dataset.category+' · '+fmt(visible);});});
async function encodeProfilePhoto(file){
 if(!file)return null;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>10*1024*1024)throw Error(T('Choose a JPG, PNG or WebP under 10 MB','اختر صورة JPG أو PNG أو WebP أقل من 10 ميجابايت'));
 const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=96;const side=Math.min(image.width,image.height);canvas.getContext('2d').drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,96,96);let encoded=canvas.toDataURL('image/jpeg',.65);if(encoded.length>7200)encoded=canvas.toDataURL('image/jpeg',.35);if(encoded.length>7200)throw Error(T('Choose a simpler image','اختر صورة أبسط'));return encoded;}finally{URL.revokeObjectURL(url)}}
