 document.querySelectorAll('[data-tdm-photo]').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file)return;input.disabled=true;try{const encoded=await encodeProfilePhoto(file);const result=await api.call('saveTdmPhoto',{rep:input.dataset.tdmPhoto,image:encoded});state.appSettings.tdmPhotos=result.photos;render();toast(T('Photo saved for all users','تم حفظ الصورة لكل المستخدمين'));}catch(e){toast(e.message)}finally{input.disabled=false;}});
 document.querySelectorAll('[data-user-photo]').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file)return;input.disabled=true;try{const encoded=await encodeProfilePhoto(file);const result=await api.call('saveUserPhoto',{username:input.dataset.userPhoto,image:encoded});state.users=result.users||state.users;if(result.user&&state.me?.username===result.user.username)state.me=result.user;render();toast(T('User photo saved','تم حفظ صورة المستخدم'));}catch(e){toast(e.message)}finally{input.disabled=false;}});
